<?php
declare(strict_types=1);

/**
 * NEXUS SUPER4.1 PHP Edition
 * - Serves the original browser application without changing its UI or embedded assets.
 * - Provides a PHP JSON API for health checks and optional session-scoped state backup.
 * - Browser-only interactions remain in the original client-side script by design.
 */

const NEXUS_APP_VERSION = '4.1';
const NEXUS_APP_NAME = 'NEXUS SUPER4.1';
const NEXUS_ORIGINAL_CSP_HASH = 'sha256-czyDNANhyJ0pgyek/w04TrEtOusCwAWwPkPM4pxg1Uk=';

function nexus_storage_dir(): string {
    $configured = getenv('NEXUS_STORAGE_DIR');
    $dir = $configured !== false && $configured !== '' ? $configured : __DIR__ . DIRECTORY_SEPARATOR . 'storage';
    return rtrim($dir, DIRECTORY_SEPARATOR);
}

function nexus_json_response(array $payload, int $status = 200): never {
    http_response_code($status);
    header('Content-Type: application/json; charset=utf-8');
    header('Cache-Control: no-store, private');
    header('X-Content-Type-Options: nosniff');
    echo json_encode($payload, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES | JSON_INVALID_UTF8_SUBSTITUTE);
    exit;
}

function nexus_start_session(): void {
    if (session_status() === PHP_SESSION_ACTIVE) return;
    $secure = isset($_SERVER['HTTPS']) && $_SERVER['HTTPS'] !== '' && strtolower((string)$_SERVER['HTTPS']) !== 'off';
    session_name('NEXUSSESSID');
    session_set_cookie_params([
        'lifetime' => 0,
        'path' => '/',
        'secure' => $secure,
        'httponly' => true,
        'samesite' => 'Strict',
    ]);
    session_start();
    if (!isset($_SESSION['nexus_csrf']) || !is_string($_SESSION['nexus_csrf'])) {
        $_SESSION['nexus_csrf'] = bin2hex(random_bytes(32));
    }
}

function nexus_state_file(): string {
    $sessionId = session_id();
    $safeId = hash('sha256', $sessionId);
    return nexus_storage_dir() . DIRECTORY_SEPARATOR . 'state_' . $safeId . '.json';
}

function nexus_read_state(): mixed {
    $file = nexus_state_file();
    if (!is_file($file)) return null;
    $raw = file_get_contents($file);
    if ($raw === false || strlen($raw) > 5_000_000) return null;
    try { return json_decode($raw, true, 64, JSON_THROW_ON_ERROR); }
    catch (JsonException) { return null; }
}

function nexus_save_state(mixed $state): void {
    $dir = nexus_storage_dir();
    if (!is_dir($dir) && !mkdir($dir, 0700, true) && !is_dir($dir)) {
        throw new RuntimeException('Storage directory could not be created');
    }
    $json = json_encode($state, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES | JSON_THROW_ON_ERROR);
    if (strlen($json) > 5_000_000) throw new LengthException('State exceeds the 5 MB limit');
    $target = nexus_state_file();
    $tmp = $target . '.' . bin2hex(random_bytes(6)) . '.tmp';
    $written = file_put_contents($tmp, $json, LOCK_EX);
    if ($written === false || $written !== strlen($json)) {
        @unlink($tmp);
        throw new RuntimeException('State could not be written');
    }
    @chmod($tmp, 0600);
    if (!rename($tmp, $target)) {
        @unlink($tmp);
        throw new RuntimeException('State could not be committed');
    }
    @chmod($target, 0600);
}

function nexus_handle_api(): never {
    nexus_start_session();
    $action = (string)($_GET['api'] ?? '');
    if ($action === 'health' && $_SERVER['REQUEST_METHOD'] === 'GET') {
        $dir = nexus_storage_dir();
        $writable = is_dir($dir) ? is_writable($dir) : is_writable(dirname($dir));
        nexus_json_response([
            'ok' => true,
            'application' => NEXUS_APP_NAME,
            'version' => NEXUS_APP_VERSION,
            'runtime' => 'PHP ' . PHP_VERSION,
            'storage_writable' => $writable,
        ]);
    }
    if ($action === 'state' && $_SERVER['REQUEST_METHOD'] === 'GET') {
        nexus_json_response(['ok' => true, 'state' => nexus_read_state()]);
    }
    if ($action === 'state' && $_SERVER['REQUEST_METHOD'] === 'POST') {
        $provided = (string)($_SERVER['HTTP_X_NEXUS_CSRF'] ?? '');
        $expected = (string)($_SESSION['nexus_csrf'] ?? '');
        if ($provided === '' || $expected === '' || !hash_equals($expected, $provided)) {
            nexus_json_response(['ok' => false, 'error' => 'CSRF validation failed'], 403);
        }
        $length = (int)($_SERVER['CONTENT_LENGTH'] ?? 0);
        if ($length > 5_000_000) nexus_json_response(['ok' => false, 'error' => 'Request too large'], 413);
        $raw = file_get_contents('php://input');
        if ($raw === false || strlen($raw) > 5_000_000) nexus_json_response(['ok' => false, 'error' => 'Request too large'], 413);
        try { $state = json_decode($raw, true, 64, JSON_THROW_ON_ERROR); }
        catch (JsonException) { nexus_json_response(['ok' => false, 'error' => 'Invalid JSON'], 400); }
        try {
            nexus_save_state($state);
            nexus_json_response(['ok' => true, 'saved' => true]);
        } catch (LengthException $e) {
            nexus_json_response(['ok' => false, 'error' => $e->getMessage()], 413);
        } catch (Throwable) {
            nexus_json_response(['ok' => false, 'error' => 'Storage operation failed'], 500);
        }
    }
    if ($action === 'state' && !in_array($_SERVER['REQUEST_METHOD'], ['GET', 'POST'], true)) {
        header('Allow: GET, POST');
        nexus_json_response(['ok' => false, 'error' => 'Method not allowed'], 405);
    }
    nexus_json_response(['ok' => false, 'error' => 'Unknown API route'], 404);
}

function nexus_bridge_js(): never {
    header('Content-Type: application/javascript; charset=utf-8');
    header('Cache-Control: no-store');
    header('X-Content-Type-Options: nosniff');
    echo <<<'JS'
(() => {
  'use strict';
  const token = document.querySelector('meta[name="nexus-csrf-token"]')?.content || '';
  const apiUrl = (action) => `${location.pathname}?api=${encodeURIComponent(action)}`;
  async function request(action, options = {}) {
    const response = await fetch(apiUrl(action), {
      credentials: 'same-origin',
      cache: 'no-store',
      ...options,
      headers: { ...(options.headers || {}) }
    });
    const result = await response.json().catch(() => ({ ok: false, error: 'Invalid server response' }));
    if (!response.ok || result.ok !== true) throw new Error(result.error || `HTTP ${response.status}`);
    return result;
  }
  const bridge = Object.freeze({
    health: () => request('health'),
    loadState: async () => (await request('state')).state,
    saveState: (state) => request('state', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'X-NEXUS-CSRF': token },
      body: JSON.stringify(state)
    })
  });
  Object.defineProperty(window, 'NEXUS_PHP_API', { value: bridge, configurable: false, writable: false });
})();
JS;
    exit;
}

if (isset($_GET['api'])) nexus_handle_api();
if (($_GET['asset'] ?? '') === 'bridge') nexus_bridge_js();

nexus_start_session();
