NEXUS_HTML_GZIP_B64;

$compressedHtml = base64_decode($payload, true);
$html = $compressedHtml === false ? false : gzdecode($compressedHtml);
if (!is_string($html)) {
    http_response_code(500);
    header('Content-Type: text/plain; charset=utf-8');
    echo 'NEXUS application asset could not be decoded.';
    exit;
}

header('Content-Type: text/html; charset=utf-8');
header('X-Content-Type-Options: nosniff');
header('Referrer-Policy: no-referrer');
header('Permissions-Policy: camera=(), microphone=(), geolocation=(), payment=(), usb=(), serial=(), bluetooth=()');
header('Cache-Control: no-store');

// Allow the same-origin optional bridge while retaining the exact hash for the original inline app script.
$html = preg_replace(
    "/script-src 'sha256-[^']+';/",
    "script-src 'self' '" . NEXUS_ORIGINAL_CSP_HASH . "';",
    $html,
    1
) ?? $html;
$html = str_replace(
    '<meta name="referrer" content="no-referrer">',
    '<meta name="referrer" content="no-referrer">' . "\n" . '<meta name="nexus-csrf-token" content="' . $csrfToken . '">',
    $html
);
$html = preg_replace(
    '/<\/body\s*>/i',
    '<script src="?asset=bridge" defer></script>' . "\n" . '</body>',
    $html,
    1
) ?? $html;
echo $html;
